def _simulated_search(query: str, k: int = 3) -> list[RetrievedDoc]:
    terms = {t for t in query.lower().replace("/", " ").split() if len(t) > 2}
    scored = []
    for doc in _FAKE_DOCS:
        words = set(doc["text"].lower().split())
        overlap = len(terms & words)
        scored.append({**doc, "score": round(overlap / (len(terms) or 1), 3)})
    scored.sort(key=lambda d: d["score"], reverse=True)
    return scored[:k]


def _query_chroma(query: str, device_model: str, k: int = 3) -> list[RetrievedDoc]:
    import chromadb

    from config import settings

    client = (
        chromadb.HttpClient(host=settings.chroma_host, port=settings.chroma_port)
        if settings.chroma_host
        else chromadb.PersistentClient(path=settings.chroma_path)
    )
    collection = client.get_collection(settings.chroma_collection)
    res = collection.query(
        query_texts=[query],
        n_results=k,
        where={"device_model": device_model} if device_model else None,
    )
    return [
        {
            "source": meta.get("source", "unknown"),
            "page": meta.get("page"),
            "text": text,
            "score": round(1 - dist, 3),
        }
        for text, meta, dist in zip(res["documents"][0], res["metadatas"][0], res["distances"][0])
    ]


def schematic_rag_node(state: AgentState) -> dict:
    session = state.get("session", {})
    query = " ".join(
        filter(None, [state.get("issue"), session.get("current_step"), state["messages"][-1].content])
    )
    docs = _simulated_search(query)
    return {"context": docs, "trace": ["schematic_rag"]}
